<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CategoryController extends Controller { public function index(){return view('admin.categories.index',['categories'=>Category::withCount('articles')->orderBy('name')->paginate(50)]);} public function create(){return view('admin.categories.form',['category'=>new Category]);} public function store(Request $r){$d=$this->v($r);$d['slug']=$this->slug($d['name'],$d['slug']??null);$c=Category::create($d);return redirect()->route('admin.categories.edit',$c)->with('ok','Category created.');} public function edit(Category $category){return view('admin.categories.form',compact('category'));} public function update(Request $r,Category $category){$d=$this->v($r);$d['slug']=$this->slug($d['name'],$d['slug']??null,$category->id);$category->update($d);return back()->with('ok','Category saved.');} public function destroy(Category $category){$category->delete();return back()->with('ok','Category deleted.');} private function v(Request $r){return $r->validate(['name'=>'required|string|max:255','slug'=>'nullable|string|max:255','description'=>'nullable|string|max:5000']);} private function slug($name,$input=null,$ignore=null){$b=Str::slug($input?:$name);$s=$b;$n=2;while(Category::where('slug',$s)->when($ignore,fn($q)=>$q->whereKeyNot($ignore))->exists())$s=$b.'-'.$n++;return $s;} }
